def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    sofa_patches = image_patch.find("sofa")
    table_patches = image_patch.find("table")

    if not sofa_patches or not table_patches:
        return image_patch

    table_depth = min(table_patch.compute_depth() for table_patch in table_patches)

    behind_sofa = [s for s in sofa_patches if s.compute_depth() > table_depth]

    if behind_sofa:
        return max(behind_sofa, key=lambda s: s.area)

    return sofa_patches[0]

